import React, { useState, useMemo, useEffect, useCallback, useRef } from "react";

/* ─────────────────────────────────────────────
   아쉬탕가 가이드 — 심야 수련 톤
   · 3개 레벨 전체 시퀀스 (초급/중급/상급)
   · 자세 상세 모달 (진입 단계 · 흔한 실수)
   · 호흡 타이머 수련 모드 (자동 진행)
   ───────────────────────────────────────────── */

/* 테마 팔레트 — applyTheme()가 C/FIG_C 값을 통째로 바꿔치기합니다 */
const THEMES = {
  dark: {
    bg: "#12171E", card: "#1A212B", cardEdge: "#242E3A",
    ink: "#E9E6DC", sub: "#8B95A0",
    amber: "#D9A05B", amberDim: "rgba(217,160,91,0.12)",
    jade: "#9DBBAA", line: "#2A3441", danger: "#C97B6B",
  },
  light: {
    bg: "#F6F3EB", card: "#FFFFFF", cardEdge: "#E7E1D2",
    ink: "#2B2F35", sub: "#68737E",
    amber: "#B27A39", amberDim: "rgba(178,122,57,0.12)",
    jade: "#5E8571", line: "#E0DACB", danger: "#B05A48",
  },
};
const C = { ...THEMES.dark };

/* ── 아웃라인 카툰 피겨 SVG ── */
const FIG_C = {
  skin: "#F2EFE2", skin2: "#E2DCC8",
  pants: "#5FB8BE", pants2: "#4CA2A8",
  top: "#FFA51F", top2: "#E8920F",
  hair: "#A18868", blush: "#F2BFA4", out: "#4A3F44",
};
const FIG_THEMES = { dark: {}, light: {} }; // 외곽선 덕에 두 테마 공용
const applyTheme = (t) => {
  Object.assign(C, THEMES[t]);
  Object.assign(FIG_C, FIG_THEMES[t]);
  if (typeof document !== "undefined") document.body.style.background = C.bg;
};
const Fig = ({ d, size = 96, glow = false }) => (
  <svg className="pv" viewBox="0 0 100 100" width={size} height={size} aria-hidden="true">
    <line x1="8" y1="90" x2="92" y2="90" stroke={C.line} strokeWidth="2" />
    <g style={glow ? { filter: "drop-shadow(0 0 7px rgba(217,160,91,0.35))" } : undefined}>
      {d.map((el, i) => {
        if (el.f) {
          if (el.c) return <circle key={i} cx={el.c[0]} cy={el.c[1]} r={el.c[2]} fill={FIG_C[el.f]} stroke={el.o === 0 ? "none" : FIG_C.out} strokeWidth={1.7} />;
          return <path key={i} d={el.p} fill={FIG_C[el.f]} stroke={FIG_C.out} strokeWidth={1.7} strokeLinejoin="round" />;
        }
        const common = { key: i, stroke: FIG_C[el.k], strokeWidth: el.w, strokeLinecap: "round", fill: "none" };
        if (el.l) return <line {...common} x1={el.l[0]} y1={el.l[1]} x2={el.l[2]} y2={el.l[3]} />;
        if (el.p) return <path {...common} d={el.p} />;
        return null;
      })}
    </g>
  </svg>
);

/* ── 사진 우선, 없으면 스틱 피겨 ──
   public/photos/ 폴더에 "자세이름.jpg"(ko 필드의 " · " 앞부분)로 사진을 넣으면
   해당 자세에 자동으로 표시되고, 파일이 없거나 로딩에 실패하면 스틱 피겨로 대체됩니다.
   예) public/photos/사마스티티.jpg → 사마스티티 자세에 표시 */
const poseImg = (koName) =>
  koName ? `/photos/${encodeURIComponent(koName.split(" · ")[0].trim())}.jpg` : null; /* 언어 경로(/en/ 등) 아래에서도 동작하도록 절대 경로 */

/* ── 자세잡기 동영상 (시작 자세 → 완성 자세) ──
   public/videos/poses/<한글이름>.mp4 를 넣으면 카드의 "자세잡기" 버튼에서 재생됩니다.
   파일이 아직 없으면 EntryVideo가 "준비 중" 안내를 보여줍니다. */
const poseVid = (koName) =>
  koName ? `/videos/poses/${encodeURIComponent(koName.split(" · ")[0].trim())}.mp4` : null;
const PoseVisual = ({ pose, size = 96, glow = false, video = false }) => {
  const src = pose.photo || poseImg(pose.ko || pose.name);
  const [failed, setFailed] = useState(false);
  const [vidFailed, setVidFailed] = useState(false);
  useEffect(() => setFailed(false), [src]);
  useEffect(() => setVidFailed(false), [pose.vid]);
  const box = {
    width: size, height: size, objectFit: "contain", background: "#fff", borderRadius: 12,
    border: `1px solid ${C.cardEdge}`, flexShrink: 0,
    ...(glow ? { boxShadow: "0 0 14px rgba(157,187,170,0.35)" } : {}),
  };
  if (video && pose.vid && !vidFailed) {
    return (
      <video
        key={pose.vid}
        className="pv"
        src={pose.vid}
        autoPlay
        playsInline
        muted
        ref={(el) => { if (el) el.muted = true; }} /* React가 muted 속성을 DOM에 안 쓰는 문제 대비 */
        poster={src || undefined}
        aria-label={pose.ko || pose.name || ""}
        onError={() => setVidFailed(true)}
        style={{ ...box, objectFit: "cover" }}
      />
    );
  }
  if (src && !failed) {
    return (
      <img
        className="pv"
        src={src}
        alt={pose.ko || pose.name || ""}
        onError={() => setFailed(true)}
        loading="lazy"
        style={box}
      />
    );
  }
  return <Fig d={pose.fig} size={size} glow={glow} />;
};

/* 자세잡기 동영상 패널 — 카드 안에서 펼쳐져 자동 재생, 종료 후 완성 자세에서 정지 */
function EntryVideo({ src, lang, onClose }) {
  const [failed, setFailed] = useState(false);
  const ref = useRef(null);
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 10, padding: "4px 16px 16px" }}>
      {failed ? (
        <p style={{ fontSize: 13, color: C.sub }}>
          {lang === "ko" ? "이 자세의 동작 영상은 준비 중이에요." : "The entry video for this pose is coming soon."}
        </p>
      ) : (
        <video
          src={src}
          autoPlay
          playsInline
          muted
          ref={(el) => { ref.current = el; if (el) el.muted = true; }} /* React가 muted를 DOM에 안 쓰는 문제 대비 */
          onError={() => setFailed(true)}
          style={{ width: "min(380px, 100%)", borderRadius: 12, background: "#fff", border: `1px solid ${C.cardEdge}` }}
        />
      )}
      <div style={{ display: "flex", gap: 8 }}>
        {!failed && (
          <button className="pbtn" style={{ fontSize: 12.5 }}
            onClick={() => { const v = ref.current; if (v) { v.currentTime = 0; v.play(); } }}>
            {lang === "ko" ? "다시 보기" : "Replay"}
          </button>
        )}
        <button className="pbtn" style={{ fontSize: 12.5 }} onClick={onClose}>{lang === "ko" ? "닫기" : "Close"}</button>
      </div>
    </div>
  );
}

